function Avatar({bird,size=56}){
  return <div style={{width:size,height:size,borderRadius:"50%",flexShrink:0,background:bird.photo?`url(${bird.photo}) center/cover no-repeat`:PAT_BG[bird.pattern]||"#333",border:`3px solid ${SC[bird.sex]}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:size*.4,fontWeight:800,boxShadow:"0 2px 12px rgba(0,0,0,0.5)",color:isLight(bird.pattern)?"#222":"#fff"}}>{!bird.photo&&bird.name[0]}</div>;
}
function Tag({label,color="#7c3aed"}){return <span style={{background:color+"22",border:`1px solid ${color}55`,color,borderRadius:20,padding:"2px 10px",fontSize:11,fontWeight:600,whiteSpace:"nowrap"}}>{label}</span>;}
function SecTitle({t}){return <div style={{color:"#c084fc",fontSize:11,fontWeight:700,letterSpacing:1,textTransform:"uppercase",marginBottom:8,marginTop:16}}>{t}</div>;}
function SelBtn({label,active,onClick,small=false}){return <button onClick={onClick} style={{padding:small?"5px 10px":"8px 14px",borderRadius:9,border:`1.5px solid ${active?"#c084fc":"rgba(255,255,255,0.12)"}`,background:active?"rgba(124,58,237,0.3)":"rgba(255,255,255,0.04)",color:active?"#c084fc":"#a0a0c0",fontSize:small?11:12,fontWeight:600,cursor:"pointer",flexShrink:0}}>{label}</button>;}

function PhotoUploader({onPhoto,label="Subir foto"}){
  const r=useRef();
  return <><input type="file" accept="image/*" ref={r} style={{display:"none"}} onChange={e=>{const f=e.target.files[0];if(!f)return;const rd=new FileReader();rd.onload=ev=>onPhoto(ev.target.result);rd.readAsDataURL(f);}}/><button onClick={()=>r.current.click()} style={{background:"rgba(124,58,237,0.15)",border:"1px dashed rgba(124,58,237,0.5)",borderRadius:10,padding:"10px 16px",color:"#c084fc",fontSize:13,cursor:"pointer",width:"100%"}}>📷 {label}</button></>;
}

// Visual selector with reference image overlay
function VisualSelector({title,refImage,options,value,onChange,imageAlt}){
  const [showImg,setShowImg]=useState(false);
  return(
    <div style={{marginBottom:14}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
        <label style={LS}>{title}</label>
        <button onClick={()=>setShowImg(s=>!s)} style={{background:"rgba(124,58,237,0.2)",border:"1px solid rgba(124,58,237,0.4)",borderRadius:8,padding:"3px 10px",color:"#c084fc",fontSize:11,cursor:"pointer"}}>
          {showImg?"Ocultar guía":"Ver guía 📷"}
        </button>
      </div>
      {showImg&&<div style={{marginBottom:10,borderRadius:12,overflow:"hidden",border:"1px solid rgba(255,255,255,0.1)"}}>
        <img src={refImage} alt={imageAlt} style={{width:"100%",display:"block"}}/>
        <div style={{background:"rgba(0,0,0,0.6)",padding:"6px 10px",fontSize:11,color:"#c084fc",textAlign:"center"}}>Referencia visual — toca para cerrar</div>
      </div>}
      <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
        {options.map(o=><SelBtn key={o.value||o} label={o.label||o} active={(value===( o.value||o))} onClick={()=>onChange(o.value||o)} small/>)}
      </div>
    </div>
  );
}

function WeightInput({value,onChange}){
  const oz = parseFloat(value)||0;
  const warn = oz>13 && oz>0;
  return(
    <div style={{marginBottom:14}}>
      <label style={LS}>Peso (onzas)</label>
      <input type="number" step="0.1" min="0" max="30" value={value||""} onChange={e=>onChange(e.target.value)} placeholder="ej. 11.5" style={{...IS,borderColor:warn?"#ef4444":"rgba(255,255,255,0.13)"}}/>
      {warn&&<div style={{background:"rgba(239,68,68,0.15)",border:"1px solid rgba(239,68,68,0.4)",borderRadius:8,padding:"8px 12px",marginTop:6,display:"flex",gap:8,alignItems:"center"}}>
        <span style={{fontSize:18}}>⚠️</span>
        <div>
          <div style={{color:"#ef4444",fontSize:12,fontWeight:700}}>Peso superior a 13 oz</div>
          <div style={{color:"#fca5a5",fontSize:11}}>Este animal podría no cualificar para competencias de kiris enanos</div>
        </div>
      </div>}
    </div>
  );
}

